<?php
declare(strict_types=1);namespace Joomleague\Component\Joomleague\Site\Model;defined('_JEXEC')or die;
use Joomla\CMS\Factory;use Joomla\CMS\MVC\Model\BaseDatabaseModel;use Joomla\Database\DatabaseInterface;use Joomleague\Component\Joomleague\Domain\Service\EventRankingReader;
final class EventrankingModel extends BaseDatabaseModel{protected function populateState($ordering=null,$direction=null):void{$i=Factory::getApplication()->getInput();$this->setState('project_id',$i->getInt('project_id',0));$this->setState('event_code',$i->getCmd('event_code',''));}/** @return array<string,mixed> */public function getRanking():array{$id=(int)$this->getState('project_id');if($id<1)return['error'=>'COM_JOOMLEAGUE_EVENTRANKING_NO_PROJECT'];Factory::getApplication()->bootComponent('com_joomleague');try{$code=trim((string)$this->getState('event_code'))?:null;return(new EventRankingReader(Factory::getContainer()->get(DatabaseInterface::class)))->forProject($id,$code,100,Factory::getApplication()->getIdentity()->getAuthorisedViewLevels());}catch(\Throwable){return['error'=>'COM_JOOMLEAGUE_EVENTRANKING_UNAVAILABLE'];}}}
